try{saved=JSON.parse(localStorage.getItem('hd-saved'))||saved;prefs={...prefs,...JSON.parse(localStorage.getItem('hd-prefs')||'{}')};}catch{}
let screen=document.body.dataset.page||'feed',feed='top',selected=1,query='',viewMode='bilingual',summaryMode='article',digestCategory='全部',lastScreen='feed',lastScroll=0,toastTimer,shortcutTrigger=null,dirty=false,job=null;
const feedNames={top:'热门故事',new:'最新发布',best:'最佳精选',ask:'社区提问',show:'作品展示',jobs:'招聘信息'};
const persist=()=>{try{localStorage.setItem('hd-saved',JSON.stringify(saved));localStorage.setItem('hd-prefs',JSON.stringify(prefs));}catch{}};
function applyTheme(){document.documentElement.classList.toggle('dark',prefs.theme==='dark'||prefs.theme==='system'&&matchMedia('(prefers-color-scheme: dark)').matches)}applyTheme();
matchMedia('(prefers-color-scheme: dark)').addEventListener('change',()=>{if(prefs.theme==='system')applyTheme()});
function toast(t){$('#toast').textContent=t;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,3200)}
const btn=(text,action,cls='',i='')=>`<button type="button" class="btn ${cls}" data-action="${action}">${i?icon(i):''}${text}</button>`;
const navItem=(id,text,i,key='')=>`<button type="button" data-nav="${id}" class="${(screen==='feed'&&feed===id)||screen===id?'active':''}" ${((screen==='feed'&&feed===id)||screen===id)?'aria-current="page"':''}>${icon(i)}<span>${text}</span>${key?`<kbd>${key}</kbd>`:''}</button>`;
function shell(){document.body.innerHTML=`<div class="app" id="app"><aside class="sidebar" aria-label="主导航"><div class="brand"><span class="mark">h</span>HackDigest</div><div class="nav-label">发现 / DISCOVER</div><nav class="nav" aria-label="故事分类">${[['top','热门','home'],['new','最新','clock'],['best','最佳','star'],['ask','提问','ask'],['show','展示','show'],['jobs','招聘','jobs']].map((n,i)=>navItem(...n,String(i+1))).join('')}</nav><div class="nav-label">阅读 / LIBRARY</div><nav class="nav" aria-label="阅读与设置">${navItem('digest','每日摘要','digest')}${navItem('bookmarks','我的收藏','bookmark')}${navItem('settings','设置','settings')}</nav><div class="sidebar-foot"><div class="connection"><span class="dot"></span>本地原型 · 未连接服务</div><div class="actions"><button class="iconbtn" data-action="theme" aria-label="切换亮暗主题">${icon('sun')}</button><button class="iconbtn" data-action="shortcuts" aria-label="快捷键帮助">${icon('keyboard')}</button></div></div></aside><main class="main"><header class="topbar"><button class="iconbtn mobile-menu" data-action="menu" aria-label="展开导航" aria-expanded="false">${icon('menu')}</button><div class="breadcrumbs">HackDigest <span aria-hidden="true">/</span> <span id="crumb"></span></div><label class="search">${icon('search')}<span class="sr-only" style="position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)">搜索故事</span><input id="search" aria-label="搜索标题或来源" placeholder="搜索标题或来源…" value="${esc(query)}"><kbd>/</kbd></label><button class="iconbtn" data-action="shortcuts" aria-label="查看快捷键">${icon('keyboard')}</button></header><div class="page" id="page"></div></main></div><div class="toast" id="toast" role="status" hidden></div><dialog class="modal" id="shortcuts" aria-labelledby="shortcut-title"><div class="modal-head"><h2 id="shortcut-title">键盘快捷键</h2><button class="iconbtn" data-action="close-shortcuts" aria-label="关闭快捷键">${icon('close')}</button></div><p class="helper">输入文字时不会触发阅读快捷键。</p><div class="shortcut-grid">${shortcutContent()}</div></dialog><dialog class="modal" id="reset-dialog" aria-labelledby="reset-title"><div class="modal-head"><h2 id="reset-title">恢复默认偏好？</h2></div><p>将重置翻译和外观偏好，不会删除收藏。</p><div class="actions" style="margin-top:24px">${btn('取消','cancel-reset')}${btn('恢复默认','confirm-reset','primary')}</div></dialog>`;render();}
function shortcutContent(){return [['阅读导航',[['选择上一条 / 下一条','k','j'],['打开选中故事','Enter'],['返回列表','u'],['切换故事分类','1–6'],['聚焦搜索','/'],['刷新演示列表','r']] ],['翻译与收藏',[['翻译选中标题','t'],['批量翻译当前列表 / 评论','Shift','T'],['打开故事摘要','d'],['收藏 / 取消收藏','s'],['每日摘要','g','d'],['收藏列表','g','b'],['帮助 / 关闭浮层','?','Esc']]]].map(([title,rows])=>`<section class="shortcut-group"><h3>${title}</h3>${rows.map(([label,...keys])=>`<div class="shortcut-row"><span>${label}</span><span class="keys">${keys.map(k=>`<kbd>${k}</kbd>`).join('')}</span></div>`).join('')}</section>`).join('')}
function pageHead(title,desc,actions='',eyebrow=''){return `<div class="pagehead"><div>${eyebrow?`<div class="eyebrow">${eyebrow}</div>`:''}<h1>${title}</h1><p class="helper">${desc}</p></div><div class="actions">${actions}</div></div>`}
function bottom(){return `<footer class="bottomline"><span class="keyhints"><kbd>j</kbd> <kbd>k</kbd> 选择　<kbd>↵</kbd> 阅读　<kbd>s</kbd> 收藏　<kbd>?</kbd> 帮助</span><span>示例内容 · 翻译与摘要为本地演示</span></footer>`}
function filtered(){let rows=stories.filter(s=>screen!=='bookmarks'||saved.includes(s.id));if(screen==='feed'){if(feed==='new')rows.sort((a,b)=>parseInt(a.time)-parseInt(b.time));if(feed==='best')rows.sort((a,b)=>b.points-a.points);if(feed==='ask')rows=rows.filter(s=>s.en.startsWith('Ask'));if(feed==='show')rows=rows.filter(s=>s.en.startsWith('Show'));if(feed==='jobs')rows=rows.filter(s=>s.id===5)}return rows.filter(s=>`${s.en} ${s.zh} ${s.domain} ${s.category}`.toLowerCase().includes(query.toLowerCase().trim()))}
function storyRow(s,i){return `<article class="story-row ${selected===s.id?'selected':''}" data-id="${s.id}"><span class="rank">${String(i+1).padStart(2,'0')}</span><div><button class="story-title" data-story="${s.id}">${esc(s.translated&&viewMode!=='original'?s.zh:s.en)}</button>${s.translated&&viewMode==='bilingual'?`<p class="original">${esc(s.en)}</p>`:''}<div class="meta"><span>${esc(s.domain)}</span><span>${s.points} 分</span><button data-story="${s.id}" data-comments="true">${s.comments} 条讨论</button><span>${s.time}</span>${s.summary?`<button class="status" data-summary="${s.id}">摘要可读 ↗</button>`:''}${s.translated?'<span>机译示例</span>':'<button class="status" data-translate="'+s.id+'">翻译标题</button>'}</div></div><button class="bookmark" data-save="${s.id}" aria-label="${saved.includes(s.id)?'取消收藏':'收藏'}：${esc(s.zh)}" aria-pressed="${saved.includes(s.id)}">${icon('bookmark')}</button></article>`}
function renderList(){const rows=filtered();if(!rows.some(s=>s.id===selected))selected=rows[0]?.id||null;$('#results').innerHTML=rows.length?rows.map(storyRow).join(''):`<div class="empty"><h2>${query?'没有匹配的故事':'这里还没有收藏'}</h2><p>${query?'试试标题中的词语，或按来源搜索。':'在故事旁点击书签，稍后在这里继续阅读。'}</p>${btn(query?'清空搜索':'浏览热门',query?'clear-search':'go-feed')}</div>`;$('#result-count').textContent=`${rows.length} 条${query?'搜索结果':'故事'}`;}
function feedView(){const title=screen==='bookmarks'?'我的收藏':feedNames[feed];return pageHead(title,screen==='bookmarks'?'留住值得读第二次的内容。':'从社区发现值得读的内容，用你的语言理解。',`${btn('刷新','refresh','','refresh')}${btn('翻译本页','translate-all','primary','translate')}`,'HACKER NEWS / READER')+(screen==='feed'?`<section class="daily-banner"><div><h2>少一点信息负担，多一点收获。</h2><p class="helper">今日摘要 · 按主题整理本页 ${stories.length} 条示例故事</p></div><button class="textbtn" data-nav="digest">阅读每日摘要 ${icon('arrow')}</button></section>`:'')+`<div class="feed-layout"><section aria-label="故事列表"><div class="listhead"><span id="result-count"></span><div class="seg" aria-label="标题显示方式">${[['bilingual','双语'],['translated','译文'],['original','原文']].map(([v,t])=>`<button data-mode="${v}" aria-pressed="${viewMode===v}">${t}</button>`).join('')}</div></div><div id="results"></div></section><aside class="reading-aside"><section class="aside-section"><div class="eyebrow">YOUR READING SPACE</div><h2>把注意力留给内容</h2><p>先看标题，再读摘要。真正感兴趣时，进入原文和讨论。</p></section><section class="aside-section"><h2>三种方式，读懂故事</h2><button class="feature-link" data-summary="1">原文摘要 ${icon('arrow')}</button><button class="feature-link" data-discussion="1">讨论摘要 ${icon('arrow')}</button><button class="feature-link" data-nav="digest">每日摘要 ${icon('arrow')}</button></section><section class="aside-section"><h2>你的阅读清单</h2><p class="big">${saved.length}<small style="font:13px var(--font);margin-left:8px;color:var(--mute)">条已收藏</small></p><button class="textbtn" data-nav="bookmarks">继续阅读 ${icon('arrow')}</button></section><section class="aside-section"><p>当前为交互原型，未抓取实时新闻，也未调用模型。</p></section></aside></div>${bottom()}`}
function summaryMarkup(s){return `<div class="summary-head"><h2>读懂这篇故事</h2><div class="seg" aria-label="摘要类型"><button data-summary-mode="article" aria-pressed="${summaryMode==='article'}">原文摘要</button><button data-summary-mode="discussion" aria-pressed="${summaryMode==='discussion'}">讨论摘要</button></div></div><p class="helper">摘要演示 · 仅使用当前示例内容 · 非实时模型输出</p><ul>${(summaryMode==='article'?[s.body,'阅读完整内容时，请核对原文的适用前提、证据和限制。']:['讨论关注方案的适用边界，以及备份、恢复和维护成本。','以下评论仅为交互演示，不代表真实用户观点。']).map(t=>`<li>${esc(t)}</li>`).join('')}</ul><div class="summary-foot"><span class="helper">保留原文，便于核对</span><button class="textbtn" data-action="regenerate">${icon('refresh')} 重新生成演示</button></div>`}
function commentMarkup(c,i){return `<article class="comment ${i===1?'reply':''}" id="comment-${i}"><div class="comment-head"><strong>${c.name}</strong><span>示例评论</span>${c.translated?'<span>机译演示</span>':''}</div><p>${esc(c.translated?c.zh:c.en)}</p>${c.translated?`<details><summary>查看原文</summary><p>${esc(c.en)}</p></details>`:''}<div class="comment-actions"><button class="textbtn" data-comment="${i}">${c.translated?'显示英文':'翻译此评论'}</button></div></article>`}
function storyView(){const s=stories.find(x=>x.id===selected)||stories[0];selected=s.id;return `<div class="reading"><button class="textbtn back" data-action="back">${icon('back')} 返回${lastScreen==='digest'?'每日摘要':lastScreen==='bookmarks'?'收藏':'故事列表'}</button><div class="eyebrow">${esc(s.category)} / STORY</div><h1>${esc(s.translated?s.zh:s.en)}</h1>${s.translated?`<p class="original">${esc(s.en)}</p>`:''}<div class="meta"><span>${s.domain}</span><span>${s.points} 分</span><span>${s.time}</span><span>${s.comments} 条讨论 · 示例数据</span></div><div class="actions" style="margin-top:20px"><a class="btn" href="https://${s.domain}" target="_blank" rel="noopener noreferrer">访问来源网站 ${icon('external')}</a><button class="btn" data-save="${s.id}" aria-pressed="${saved.includes(s.id)}">${icon('bookmark')} ${saved.includes(s.id)?'已收藏':'收藏故事'}</button>${!s.translated?btn('翻译标题','translate-selected','','translate'):''}</div><section class="summary-box" id="summary" aria-label="故事摘要">${summaryMarkup(s)}</section><div class="section-head" id="discussion"><div class="od-field"><h2>社区讨论</h2><p class="helper">展示 ${comments.length} 条示例 · 已翻译 ${comments.filter(c=>c.translated).length} 条</p></div>${btn('翻译当前评论','translate-comments','','translate')}</div><div id="comments">${comments.map(commentMarkup).join('')}</div><p class="helper" style="margin-top:24px">原始页面未提供对应文章链接，来源按钮仅打开站点首页。</p>${bottom()}</div>`}
function digestView(){const categories=['全部',...new Set(stories.map(s=>s.category))];return pageHead('每日摘要','2026 年 11 月 10 日 · 根据本页示例内容整理',btn('重新生成演示','digest-generate','','refresh'),'THE DAILY BRIEF')+`<div class="notice">本期为布局与阅读交互示例，共 ${stories.length} 条故事。摘要不代表已核验的新闻事实。</div><div class="digest-layout"><nav class="toc" aria-label="摘要主题">${categories.map(c=>`<button data-category="${c}" aria-pressed="${digestCategory===c}" style="${digestCategory===c?'color:var(--accent);font-weight:650':''}">${c}</button>`).join('')}</nav><div>${categories.slice(1).filter(c=>digestCategory==='全部'||digestCategory===c).map(c=>`<section class="digest-group"><h2>${c} · ${stories.filter(s=>s.category===c).length} 条</h2>${stories.filter(s=>s.category===c).map(s=>`<article class="digest-card"><div class="no">${String(s.id).padStart(2,'0')} / ${s.domain}</div><h3>${esc(s.zh)}</h3><p>${esc(s.body)}</p><div class="meta"><span>${s.comments} 条讨论 · 示例</span><button class="status" data-story="${s.id}">阅读故事 →</button><button class="status" data-save="${s.id}">${saved.includes(s.id)?'取消收藏':'收藏'}</button></div></article>`).join('')}</section>`).join('')}</div></div>${bottom()}`}
function toggleSetting(k,label,help){return `<div class="setting-row"><div class="od-field"><span id="label-${k}" class="label">${label}</span><p class="helper">${help}</p></div><button type="button" class="switch" role="switch" aria-checked="${prefs[k]}" aria-labelledby="label-${k}" data-pref="${k}"></button></div>`}
function settingsView(){return pageHead('设置','按你的阅读习惯，调整翻译与摘要。',btn('恢复默认','reset'),'PREFERENCES')+`<div class="settings"><div class="notice">当前为本地交互原型。连接测试仅演示状态反馈，请勿输入真实 API 密钥。</div><section class="settings-group"><h2>模型与连接</h2><div class="settings-box"><div class="setting-row"><div class="od-field"><label for="provider">模型提供商</label><p class="helper">生产版使用你自己的模型服务</p></div><select id="provider" data-select="provider">${['GLM','DeepSeek','Qwen','Kimi','OpenAI','Ollama'].map(x=>`<option ${x===prefs.provider?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label for="demo-key">演示密钥</label><div class="actions"><input id="demo-key" type="password" autocomplete="off" placeholder="仅输入 demo-key" aria-describedby="key-help key-error"><button class="btn" data-action="reveal" aria-label="显示演示密钥">显示</button></div><p class="helper" id="key-help">密钥不会保存或发送；输入 demo-key 可体验成功状态。</p><p class="error" id="key-error" hidden></p></div><div class="setting-row"><div class="od-field"><span class="label">连接状态</span><p class="helper" id="connection-result" role="status">未连接 · 演示模式</p></div>${btn('测试演示连接','test-connection')}</div></div></section><section class="settings-group"><h2>阅读与翻译</h2><div class="settings-box"><div class="setting-row"><div class="od-field"><label for="language">目标语言</label><p class="helper">应用于标题、评论与摘要</p></div><select id="language" data-select="language">${['简体中文','English','日本語'].map(x=>`<option ${x===prefs.language?'selected':''}>${x}</option>`).join('')}</select></div>${toggleSetting('auto','自动翻译标题','生产版在列表加载后翻译可见标题')}${toggleSetting('tldr','自动生成故事摘要','生产版打开故事后生成摘要')}${toggleSetting('daily','每日摘要','生产版每天 06:00 整理热门故事')}<div class="setting-row"><div class="od-field"><label for="limit">评论翻译上限</label><p class="helper">限制每次批量翻译的处理条数</p></div><select id="limit" data-select="limit">${['20','50','100'].map(x=>`<option ${x===prefs.limit?'selected':''}>${x}</option>`).join('')}</select></div></div></section><section class="settings-group"><h2>外观与操作</h2><div class="settings-box"><div class="setting-row"><div class="od-field"><label for="theme">主题</label><p class="helper">亮暗主题使用同一套阅读层级</p></div><select id="theme" data-select="theme">${[['system','跟随系统'],['light','亮色'],['dark','暗色']].map(([v,t])=>`<option value="${v}" ${prefs.theme===v?'selected':''}>${t}</option>`).join('')}</select></div><div class="setting-row"><span class="label">键盘快捷键</span>${btn('查看快捷键','shortcuts','','keyboard')}</div></div></section><div class="savebar"><span class="helper" id="save-state">${dirty?'偏好已在当前会话应用，尚未保存':'偏好保存在当前浏览器；存储不可用时仅本次会话有效'}</span>${btn('保存偏好','save-prefs','primary')}</div></div>${bottom()}`}
function render(){const title=screen==='story'?'故事详情':screen==='digest'?'每日摘要':screen==='settings'?'设置':screen==='shortcuts'?'快捷键':screen==='bookmarks'?'我的收藏':feedNames[feed];$('#crumb').textContent=title;document.title=`${title} — HackDigest`;$$('[data-nav]').forEach(b=>{const on=(screen==='feed'&&b.dataset.nav===feed)||b.dataset.nav===screen;b.classList.toggle('active',on);if(on)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});$('#page').innerHTML=screen==='story'?storyView():screen==='digest'?digestView():screen==='settings'?settingsView():screen==='shortcuts'?`${pageHead('键盘快捷键','让阅读连贯，双手不必离开键盘。',btn('返回故事列表','go-feed'))}<div class="shortcut-grid">${shortcutContent()}</div>${bottom()}`:feedView();if(screen==='feed'||screen==='bookmarks')renderList();}
function navigate(to){if(job){clearTimeout(job);job=null}if(screen==='feed'||screen==='bookmarks')lastScroll=window.scrollY;if(feedNames[to]){screen='feed';feed=to}else screen=to;$('#app').classList.remove('menu-open');const m=$('[data-action="menu"]');if(m)m.setAttribute('aria-expanded','false');render();window.scrollTo(0,0);$('#page h1')?.setAttribute('tabindex','-1');$('#page h1')?.focus({preventScroll:true});}
function openStory(id,target){if(screen!=='story'){lastScreen=screen;lastScroll=window.scrollY}selected=Number(id);screen='story';render();window.scrollTo(0,0);const el=$(target||'.reading h1');if(el){el.setAttribute('tabindex','-1');el.focus({preventScroll:true});if(target)el.scrollIntoView({block:'start',behavior:'auto'})}}
function toggleSave(id){id=Number(id);saved=saved.includes(id)?saved.filter(x=>x!==id):[...saved,id];persist();const wasSaved=saved.includes(id);render();const b=$(`[data-save="${id}"]`);(b||$('#page h1'))?.focus();toast(wasSaved?'已加入收藏':'已取消收藏')}
function runDemo(button,label,done){if(button.disabled)return;button.disabled=true;const before=button.innerHTML;button.textContent=label;button.setAttribute('aria-busy','true');job=setTimeout(()=>{job=null;done();if(button.isConnected){button.disabled=false;button.innerHTML=before;button.removeAttribute('aria-busy')}},650)}
function translateRows(button){const rows=filtered();if(!rows.length)return toast('当前没有可翻译的故事');runDemo(button,'正在翻译演示…',()=>{rows.forEach(s=>s.translated=true);render();toast(`已显示 ${rows.length} 条标题的翻译示例`)})}
function closeHelp(){const d=$('#shortcuts');d.close();if(shortcutTrigger?.isConnected)shortcutTrigger.focus();else $('[data-action="shortcuts"]')?.focus()}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;
if(d.nav){navigate(d.nav);return}if(d.story){openStory(d.story,d.comments?'#discussion':null);return}if(d.summary){summaryMode='article';openStory(d.summary,'#summary');return}if(d.discussion){summaryMode='discussion';openStory(d.discussion,'#summary');return}if(d.save){toggleSave(d.save);return}if(d.translate){stories.find(s=>s.id===Number(d.translate)).translated=true;render();toast('已显示标题翻译示例');return}if(d.mode){viewMode=d.mode;render();$(`[data-mode="${viewMode}"]`)?.focus();return}if(d.summaryMode){summaryMode=d.summaryMode;$('#summary').innerHTML=summaryMarkup(stories.find(s=>s.id===selected));$(`[data-summary-mode="${summaryMode}"]`)?.focus();return}if(d.comment!==undefined){comments[Number(d.comment)].translated=!comments[Number(d.comment)].translated;render();$(`[data-comment="${d.comment}"]`)?.focus();return}if(d.category){digestCategory=d.category;render();$(`[data-category="${digestCategory}"]`)?.focus();return}if(d.pref){prefs[d.pref]=!prefs[d.pref];dirty=true;b.setAttribute('aria-checked',prefs[d.pref]);$('#save-state').textContent='偏好已在当前会话应用，尚未保存';return}
switch(d.action){case'menu':$('#app').classList.toggle('menu-open');b.setAttribute('aria-expanded',$('#app').classList.contains('menu-open'));break;case'theme':prefs.theme=document.documentElement.classList.contains('dark')?'light':'dark';applyTheme();persist();toast(prefs.theme==='dark'?'已切换暗色主题':'已切换亮色主题');break;case'shortcuts':shortcutTrigger=b;$('#shortcuts').showModal();break;case'close-shortcuts':closeHelp();break;case'go-feed':navigate('top');break;case'back':screen=lastScreen;render();window.scrollTo(0,lastScroll);($(`[data-story="${selected}"]`)||$('#page h1'))?.focus({preventScroll:true});break;case'clear-search':query='';$('#search').value='';renderList();$('#search').focus();break;case'refresh':runDemo(b,'刷新演示…',()=>toast('演示列表已更新，未请求实时新闻'));break;case'translate-all':translateRows(b);break;case'translate-selected':stories.find(s=>s.id===selected).translated=true;render();toast('已显示标题翻译示例');break;case'translate-comments':runDemo(b,'正在翻译演示…',()=>{comments.forEach(c=>c.translated=true);render();toast('已显示当前评论的翻译示例')});break;case'regenerate':runDemo(b,'正在生成演示…',()=>toast('摘要演示已完成，未调用模型'));break;case'digest-generate':runDemo(b,'整理示例内容…',()=>toast('已整理本页 8 条示例故事'));break;case'reveal':{let input=$('#demo-key');input.type=input.type==='password'?'text':'password';b.textContent=input.type==='password'?'显示':'隐藏';b.setAttribute('aria-label',input.type==='password'?'显示演示密钥':'隐藏演示密钥');break}case'test-connection':{const input=$('#demo-key'),err=$('#key-error');if(input.value!=='demo-key'&&prefs.provider!=='Ollama'){err.textContent='请输入 demo-key 体验演示；请勿输入真实密钥。';err.hidden=false;input.setAttribute('aria-invalid','true');input.focus();break}err.hidden=true;input.removeAttribute('aria-invalid');$('#connection-result').textContent='正在模拟连接…';runDemo(b,'测试演示中…',()=>{$('#connection-result').textContent='演示成功 · 未连接真实服务';input.value='';toast('连接反馈演示完成')});break}case'save-prefs':persist();dirty=false;$('#save-state').textContent='偏好已应用；浏览器允许存储时可在下次打开保留';toast('偏好已保存到当前会话');break;case'reset':$('#reset-dialog').showModal();break;case'cancel-reset':$('#reset-dialog').close();$('[data-action="reset"]').focus();break;case'confirm-reset':prefs={provider:'GLM',language:'简体中文',auto:true,tldr:true,daily:true,limit:'50',theme:'system'};persist();dirty=false;applyTheme();$('#reset-dialog').close();render();$('[data-action="reset"]')?.focus();toast('已恢复默认偏好');break;}
});
document.addEventListener('change',e=>{if(e.target.dataset.select){prefs[e.target.dataset.select]=e.target.value;dirty=true;if(e.target.dataset.select==='theme')applyTheme();$('#save-state').textContent='偏好已在当前会话应用，尚未保存';if(e.target.dataset.select==='provider'){$('#connection-result').textContent='提供商已切换 · 未连接';$('#key-error').hidden=true;$('#demo-key').value=''}}});
document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;if(!['feed','bookmarks'].includes(screen)){screen='feed';render()}else renderList()}});
let pendingG=false,gTimer;
document.addEventListener('keydown',e=>{if($('#shortcuts').open){if(e.key==='Escape'){e.preventDefault();closeHelp()}return}if($('#reset-dialog').open)return;if(e.target.closest('input,textarea,select,[contenteditable=true]'))return;if(e.ctrlKey||e.metaKey||e.altKey)return;const key=e.key.toLowerCase();if(pendingG){pendingG=false;clearTimeout(gTimer);if(key==='d'){e.preventDefault();navigate('digest');return}if(key==='b'){e.preventDefault();navigate('bookmarks');return}}if(key==='g'){pendingG=true;gTimer=setTimeout(()=>pendingG=false,1200);return}if(key==='?'){e.preventDefault();shortcutTrigger=document.activeElement;$('#shortcuts').showModal();return}if(key==='/'){e.preventDefault();$('#search').focus();return}if(/^[1-6]$/.test(key)){navigate(Object.keys(feedNames)[Number(key)-1]);return}if(key==='u'||key==='arrowleft'){if(screen==='story'){e.preventDefault();$('[data-action="back"]').click()}return}if((key==='j'||key==='k')&&['feed','bookmarks'].includes(screen)){e.preventDefault();let list=filtered(),i=list.findIndex(s=>s.id===selected);selected=list[Math.max(0,Math.min(list.length-1,i+(key==='j'?1:-1)))]?.id;renderList();$(`[data-id="${selected}"]`)?.scrollIntoView({block:'nearest'});return}if(key==='enter'&&['feed','bookmarks'].includes(screen)&&!e.target.closest('button,a')){e.preventDefault();if(selected)openStory(selected);return}if(key==='s'&&['feed','bookmarks','story'].includes(screen)){e.preventDefault();if(selected)toggleSave(selected);return}if(key==='d'&&selected&&screen!=='settings'){e.preventDefault();summaryMode='article';openStory(selected,'#summary');return}if(key==='t'){e.preventDefault();if(e.shiftKey){const b=$(screen==='story'?'[data-action="translate-comments"]':'[data-action="translate-all"]');b?.click()}else{const s=stories.find(s=>s.id===selected);if(s){s.translated=true;render();toast('已显示标题翻译示例')}}return}if(key==='r'){$('[data-action="refresh"]')?.click()}});
shell();
$('#shortcuts').addEventListener('cancel',e=>{e.preventDefault();closeHelp()});
$('#reset-dialog').addEventListener('cancel',()=>setTimeout(()=>$('[data-action="reset"]')?.focus(),0));
